<template><view class="page"><view class="title">门店报表</view><view class="tabs"><view v-if="can('analysis.view')" :class="{active:type==='revenue'}" @click="setType('revenue')">营业数据</view><view v-if="can('bookkeeping.manage')" :class="{active:type==='ledger'}" @click="setType('ledger')">记账本</view></view><view v-if="!allowed" class="empty">当前岗位暂未开放报表查询</view><template v-else><view class="filters"><picker :range="stores" range-key="store_name" :disabled="loading" @change="changeStore"><view class="store">{{ store?.store_name||'请选择门店' }} ▾</view></picker><view class="periods"><view v-for="p in periods" :key="p.key" :class="{active:mode===p.key}" @click="preset(p.key)">{{ p.label }}</view></view><view class="dates"><picker mode="date" :value="from" :disabled="loading" @change="from=$event.detail.value;mode='custom'"><view>{{ from }}</view></picker><text>至</text><picker mode="date" :value="to" :disabled="loading" @change="to=$event.detail.value;mode='custom'"><view>{{ to }}</view></picker></view><button class="primary" :disabled="loading||!store" @click="query">{{ loading?'查询中…':'查询报表' }}</button></view><view v-if="error" class="error">{{ error }}</view><view v-if="result"><view class="summary"><view class="muted">{{ applied.store }} · {{ applied.from }} 至 {{ applied.to }}</view><view class="label">{{ applied.type==='revenue'?'营业额':'记账金额合计' }}</view><view class="amount">¥{{ money(applied.type==='revenue'?result.summary.revenue:result.summary.amount) }}</view><view class="muted">{{ applied.type==='revenue'?'采用后台收银系统口径':'共 '+result.total+' 笔明细' }}</view><view v-if="result.summary.gross_pending" class="notice">部分营业额待补齐，当前数据以后台确认口径为准。</view></view><template v-if="applied.type==='revenue'"><view class="metrics"><view v-for="m in result.metrics" :key="m.key" class="metric"><view class="muted">{{ m.label }}</view><view class="metric-value">{{ m.type==='money'?'¥'+money(m.value):m.value }}</view><view class="muted">{{ m.sub }}</view></view></view><view v-for="section in result.sections" :key="section.key" class="card"><view class="section-title">{{ section.title }}</view><view v-for="item in section.items" :key="item.key" class="row"><view>{{ item.label }}<view class="muted">{{ item.sub }}</view></view><text>¥{{ money(item.value) }}</text></view></view></template><template v-else><view v-if="!result.total" class="empty">这个时间范围暂无记账明细</view><view v-for="entry in entries" :key="entry.id" class="card"><view class="row"><text>{{ entry.subcategory_name||entry.category_name||'未分类' }}</text><text class="entry-amount">¥{{ money(entry.amount) }}</text></view><view class="muted">{{ entry.date }} · {{ entry.store_name }}</view><view v-if="entry.remark" class="remark">{{ entry.remark }}</view><view class="muted">{{ entry.user_name||'未记录记账人' }} · 流水 {{ entry.id }}</view></view><button v-if="entries.length<result.total" :disabled="loading" @click="more">加载更多（{{ entries.length }}/{{ result.total }}）</button><view class="link" @click="uni.navigateTo({url:'/pages/bookkeeping/index'})">更多筛选与分类汇总 →</view></template></view></template></view></template>
<script setup>
import {ref,computed} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import api from '../../common/api'
import {getToken} from '../../common/request'
import {activeStore,selectStore} from '../../common/task-context'
import {localDate,money} from '../../common/format'
const user=ref({}),stores=ref([]),store=ref(null),type=ref('revenue'),mode=ref('day'),from=ref(localDate()),to=ref(localDate()),loading=ref(false),error=ref(''),result=ref(null),entries=ref([]),page=ref(1),applied=ref({})
const can=p=>(user.value.position_permissions||[]).some(v=>v==='*'||v===p),allowed=computed(()=>can(type.value==='revenue'?'analysis.view':'bookkeeping.manage'))
const periods=[{key:'day',label:'本日'},{key:'week',label:'本周'},{key:'month',label:'本月'},{key:'custom',label:'自定义'}]
function setType(key){if(loading.value)return;type.value=key;query()}
function preset(key){if(loading.value)return;mode.value=key;if(key==='custom')return;const a=new Date(),b=new Date();if(key==='week')a.setDate(a.getDate()-((a.getDay()+6)%7));if(key==='month')a.setDate(1);from.value=localDate(a);to.value=localDate(b);query()}
function changeStore(e){store.value=stores.value[Number(e.detail.value)];selectStore(store.value);query()}
async function query(){if(loading.value||!allowed.value||!store.value)return;loading.value=true;error.value='';result.value=null;entries.value=[];page.value=1;const queryType=type.value,storeName=store.value.store_name;const filters={store_id:store.value.id,date_from:from.value,date_to:to.value};try{if(from.value>to.value)throw new Error('开始日期不能晚于结束日期');const data=queryType==='revenue'?await api.revenueRange(filters):await api.bookkeepingList({...filters,page:1,page_size:30});result.value=data;entries.value=data.entries||[];applied.value={...filters,store:storeName,from:filters.date_from,to:filters.date_to,type:queryType}}catch(e){error.value=e.message}finally{loading.value=false}}
async function more(){loading.value=true;try{const data=await api.bookkeepingList({store_id:applied.value.store_id,date_from:applied.value.from,date_to:applied.value.to,page:page.value+1,page_size:30});entries.value.push(...data.entries);page.value++}catch(e){error.value=e.message}finally{loading.value=false}}
onShow(async()=>{if(!getToken())return uni.reLaunch({url:'/pages/login/login'});try{user.value=(await api.me()).user;const requested=uni.getStorageSync('mp_report_type');uni.removeStorageSync('mp_report_type');if(requested)type.value=requested;if(!allowed.value)type.value=can('analysis.view')?'revenue':'ledger';if(!allowed.value)return;const options=can('analysis.view')?await api.storeList():await api.bookkeepingOptions();stores.value=options.stores;store.value=stores.value.find(s=>s.id===activeStore()?.id)||stores.value[0]||null;if(store.value)selectStore(store.value);await query()}catch(e){error.value=e.message}})
</script>
<style scoped>.page{padding:32rpx}.title{font-size:40rpx;font-weight:700;margin-bottom:30rpx}.tabs,.periods{display:flex;gap:8rpx}.tabs{margin-bottom:24rpx}.tabs view{padding:20rpx 30rpx;color:#7e8990;font-weight:600}.tabs .active{color:#d94f2b;border-bottom:4rpx solid #d94f2b}.filters,.card{background:#fff;border-radius:24rpx;padding:28rpx;margin-bottom:22rpx}.store{font-size:30rpx;font-weight:600}.periods{margin:28rpx 0;background:#f5f6f8;border-radius:14rpx;padding:6rpx}.periods view{flex:1;font-size:24rpx;text-align:center;padding:16rpx 0}.periods .active{background:#fff;color:#d94f2b;border-radius:12rpx}.dates{display:flex;justify-content:space-between;align-items:center;font-size:26rpx}.dates picker{background:#f5f6f8;padding:18rpx 22rpx;border-radius:12rpx}.primary{background:#d94f2b;color:#fff;font-size:28rpx;margin-top:24rpx}.summary{background:#fff1e9;border-radius:24rpx;padding:32rpx;margin:28rpx 0}.muted{color:#8b949c;font-size:24rpx;line-height:1.7}.label{font-size:27rpx;margin-top:28rpx}.amount{font-size:54rpx;font-weight:700;margin:16rpx 0;color:#d94f2b}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:18rpx;margin-bottom:24rpx}.metric{background:#fff;padding:26rpx;border-radius:18rpx}.metric-value{font-weight:700;font-size:34rpx;margin:12rpx 0}.section-title{font-size:30rpx;font-weight:600;margin-bottom:16rpx}.row{display:flex;justify-content:space-between;gap:24rpx;padding:18rpx 0;font-size:27rpx}.entry-amount{color:#d94f2b;font-weight:600}.remark{font-size:26rpx;margin:16rpx 0}.empty{padding:60rpx 0;color:#8b949c;text-align:center}.error,.notice{color:#b94b2c;font-size:26rpx;padding:20rpx}.link{color:#d94f2b;text-align:center;padding:26rpx;font-size:26rpx}</style>
